<template><li><button :class="{selected:item.path===selected}" @click="item.type==='file'&&$emit('select',item.path)"><Folder v-if="item.type==='directory'" :size="14" /><FileText v-else :size="14" />{{ item.name }}</button><ul v-if="item.children?.length"><SkillTreeNode v-for="child in item.children" :key="child.path" :item="child" :selected="selected" @select="$emit('select',$event)" /></ul></li></template>
<script setup>import{FileText,Folder}from"lucide-vue-next";defineOptions({name:"SkillTreeNode"});defineProps({item:Object,selected:String});defineEmits(["select"]);</script>
